test('.port parses the port of the effective host when trustProxy is enabled', (t) => {
  const fixtures = [
    {
      name: 'x-forwarded-host wins over host',
      expected: { host: 'example.com:8080', hostname: 'example.com', port: 8080 },
      headers: {
        host: 'localhost:3000',
        'x-forwarded-host': 'example.com:8080'
      }
    },
    {
      name: 'the last x-forwarded-host entry is used',
      expected: { host: 'example.com:8080', hostname: 'example.com', port: 8080 },
      headers: {
        host: 'localhost:3000',
        'x-forwarded-host': 'proxy.example.com:1111, example.com:8080'
      }
    },
    {
      name: 'x-forwarded-host without a port',
      expected: { host: 'example.com', hostname: 'example.com', port: null },
      headers: {
        host: 'localhost:3000',
        'x-forwarded-host': 'example.com'
      }
    },
    {
      name: 'IPV6 x-forwarded-host',
      expected: { host: '[::1]:8080', hostname: '[::1]', port: 8080 },
      headers: {
        host: 'localhost:3000',
        'x-forwarded-host': '[::1]:8080'
      }
    },
    {
      name: 'host is used when x-forwarded-host is missing',
      expected: { host: 'localhost:3000', hostname: 'localhost', port: 3000 },
      headers: {
        host: 'localhost:3000'
      }
    },
    {
      name: ':authority is used when host and x-forwarded-host are missing',
      expected: { host: '1.2.3.4:80', hostname: '1.2.3.4', port: 80 },
      headers: {
        ':authority': '1.2.3.4:80'
      }
    },
    {
      name: 'no host at all',
      expected: { host: '', hostname: '', port: null },
      headers: {}
    }
  ]

  const TpRequest = Request.buildRequest(Request, true)

  for (const fixture of fixtures) {
    const req = new TpRequest(1, {}, {
      socket: { remoteAddress: '1.1.1.1' },
      headers: fixture.headers
    }, '', {}, {})

    t.assert.deepStrictEqual(
      { host: req.host, hostname: req.hostname, port: req.port },
      fixture.expected,
      fixture.name
    )
  }
})

